const nodes=[{x:190,y:380,area:'lab'},{x:365,y:377,area:'west'},{x:580,y:377,area:'main'},{x:790,y:377,area:'east'},{x:547,y:320,area:'controlLink'},{x:545,y:225,area:'control'},{x:710,y:245,area:'upperLink'},{x:900,y:195,area:'freezer'},{x:840,y:430,area:'railLink'},{x:955,y:550,area:'rail'},{x:430,y:475,area:'coreLink'},{x:430,y:620,area:'core'},{x:400,y:342,area:'ventA'},{x:517,y:305,area:'ventB'},{x:680,y:257,area:'ventC'},{x:807,y:340,area:'ventD'},{x:453,y:470,area:'ventE'},{x:1110,y:740,area:'railConnector'},{x:850,y:770,area:'railSpan'},{x:1400,y:770,area:'railSpan'}];
const links=[[0,1],[1,2],[2,3],[2,4],[4,5],[5,6],[6,7],[7,15],[3,8],[8,9],[1,10],[10,11],[12,13],[13,14],[14,15],[12,0],[13,4],[15,8],[16,10],[16,12],[9,17],[17,18],[18,19]];
const hides=[{x:112,y:300,label:'SPECIMEN CABINET',type:'cabinet'},{x:250,y:460,label:'STORAGE CRATE',type:'crate'},{x:475,y:200,label:'SERVER RACK',type:'rack'},{x:612,y:270,label:'CONSOLE BANK',type:'console'},{x:1010,y:250,label:'COLD LOCKER',type:'locker'},{x:1033,y:590,label:'CARGO PALLET',type:'crate'},{x:330,y:685,label:'CORE HOUSING',type:'rack'}];
let dpr=1, scale=1, ox=0, oy=0, running=false, timeLeft=180, stamina=100, floor=1;
let crouching=false, flashlight=false, whistleCooldown=0, toastTimer=0, monitor=false, camIndex=0, muted=true, trainX=90, trainDir=1, shake=0;
const keys={}, touch={x:0,y:0};
const tasks=[{id:'containment',name:'Stabilize containment',x:165,y:365,done:false},{id:'security',name:'Restore security uplink',x:590,y:250,done:false},{id:'coolant',name:'Reroute freezer coolant',x:1000,y:195,done:false}];
const exit={x:520,y:620,r:25};
const player={x:212,y:420,r:10,speed:122,alive:true,hidden:false,noise:0,face:0};
const beast={x:165,y:330,r:15,speed:90,state:'search',target:null,alert:0,stun:0,face:0};
const bots=[], names=['MARA','JUNO','ELI','SATO','VEX','NIKO','REMY','TALA','ORIN'];
const palette=['#85d5c0','#e4a866','#a7b6f0','#d685a2','#83ba87','#d1c26c','#9bb9cb','#ca8d64','#9bc985'];
function bot(x,y,i){return {x,y,r:8,speed:70+Math.random()*15,name:names[i],color:palette[i],alive:true,target:null,route:[],routeAt:0,hideTimer:0,crouch:false,alert:0,face:0,decision:Math.random()*3,noise:0};}
const botStarts=[[150,450],[240,300],[560,225],[610,228],[695,245],[910,245],[870,530],[1020,530],[380,620]];
botStarts.forEach((p,i)=>bots.push(bot(p[0],p[1],i)));
function resize(){dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);scale=Math.min(innerWidth/W,innerHeight/H);ox=(innerWidth-W*scale)/2;oy=(innerHeight-H*scale)/2;}
addEventListener('resize',resize);resize();
function inside(x,y,r){return x>=r[0]&&x<=r[0]+r[2]&&y>=r[1]&&y<=r[1]+r[3];}
function areaAt(x,y){return areas.find(a=>a.vent&&inside(x,y,a.r))||areas.find(a=>inside(x,y,a.r))||areas[0];}
function walkable(x,y){return areas.some(a=>inside(x,y,a.r));}
function moveEntity(e,dx,dy){let nx=e.x+dx,ny=e.y+dy;if(walkable(nx,e.y))e.x=nx;if(walkable(e.x,ny))e.y=ny;}
function clampEntity(e){if(walkable(e.x,e.y))return;let best=null,bd=Infinity;for(let a of areas){let[x,y,w,h]=a.r,cx=Math.max(x+3,Math.min(x+w-3,e.x)),cy=Math.max(y+3,Math.min(y+h-3,e.y)),d=(cx-e.x)**2+(cy-e.y)**2;if(d<bd){bd=d;best=[cx,cy];}}if(best){e.x=best[0];e.y=best[1];}}
function graphRoute(from,to){let si=0,ti=0,sd=Infinity,td=Infinity;nodes.forEach((n,i)=>{let a=(n.x-from.x)**2+(n.y-from.y)**2,b=(n.x-to.x)**2+(n.y-to.y)**2;if(a<sd){sd=a;si=i}if(b<td){td=b;ti=i}});let q=[si],prev={[si]:-1};while(q.length){let n=q.shift();if(n===ti)break;for(const[a,b]of links){let next=a===n?b:b===n?a:-1;if(next>=0&&prev[next]===undefined){prev[next]=n;q.push(next);}}}let path=[];if(prev[ti]!==undefined){let n=ti;while(n!==-1){path.unshift(nodes[n]);n=prev[n];}}return path;}
function steer(e,goal,speed,dt){if(!goal)return;let dx=goal.x-e.x,dy=goal.y-e.y,d=Math.hypot(dx,dy);if(d<10){e.routeAt=(e.routeAt||0)+1;return;}e.face=Math.atan2(dy,dx);let len=Math.min(d,speed*dt);moveEntity(e,dx/d*len,dy/d*len);}
function findPath(e,target){e.route=graphRoute(e,target);e.routeAt=0;e.target=target;}
function updateBots(dt){for(const b of bots){if(!b.alive)continue;b.decision-=dt;let threat=Math.hypot(b.x-beast.x,b.y-beast.y);if(threat<210){b.alert=Math.max(b.alert,5);b.hideTimer=Math.max(b.hideTimer,2+Math.random()*3);b.crouch=true;if(!b.target||b.decision<0){let s=hides.slice().sort((a,c)=>Math.hypot(c.x-beast.x,c.y-beast.y)-Math.hypot(a.x-beast.x,a.y-beast.y))[0];findPath(b,{x:s.x,y:s.y});b.decision=1.2;}}
    if(b.hideTimer>0){b.hideTimer-=dt;if(b.hideTimer<=0){b.crouch=false;b.target=null;}}
    if(!b.target||b.decision<=0){let opts=nodes.filter(n=>!areas.find(a=>a.id===n.area)?.vent),n=opts[Math.floor(Math.random()*opts.length)];findPath(b,{x:n.x+(Math.random()-.5)*35,y:n.y+(Math.random()-.5)*25});b.decision=5+Math.random()*8;}
    if(b.target){let wp=b.route[b.routeAt];if(wp&&Math.hypot(wp.x-b.x,wp.y-b.y)>12)steer(b,wp,b.crouch?32:b.speed,dt);else steer(b,b.target,b.crouch?32:b.speed,dt);if(Math.hypot(b.x-b.target.x,b.y-b.target.y)<14)b.target=null;}
    b.x=Math.max(80,Math.min(1515,b.x));clampEntity(b);
  }}
function chooseBeastTarget(){let c=[player,...bots.filter(b=>b.alive)],heard=c.filter(t=>t.noise>0),p=heard.length?heard:c;p.sort((a,b)=>Math.hypot(a.x-beast.x,a.y-beast.y)-Math.hypot(b.x-beast.x,b.y-beast.y));return p[0]||null;}
function updateBeast(dt){if(beast.stun>0){beast.stun-=dt;return;}beast.alert=Math.max(0,beast.alert-dt*.3);let c=[player,...bots.filter(b=>b.alive)],seen=null,best=Infinity;for(const t of c){let d=Math.hypot(t.x-beast.x,t.y-beast.y),r=t===player?(crouching?95:flashlight?290:190):(t.crouch?100:180),dark=areas.some(a=>a.vent&&inside(t.x,t.y,a.r));if(dark&&!(t===player&&flashlight))r*=.42;if(t.noise>0)r=Math.max(r,330);if(d<r&&d<best){best=d;seen=t;}}
  if(seen){beast.target=seen;beast.state=best<120?'CHASE':'INVESTIGATE';beast.alert=1;}else if(!beast.target||Math.hypot(beast.target.x-beast.x,beast.target.y-beast.y)<22){beast.target=chooseBeastTarget();beast.state=beast.alert>.1?'SEARCH':'PATROL';}
  if(!beast.target)return;let t=beast.target,slow=areas.some(a=>a.id==='freezer'&&inside(beast.x,beast.y,a.r))?.53:1;steer(beast,t,(beast.state==='CHASE'?beast.speed*1.3:beast.speed)*slow,dt);if(beast.state==='CHASE'&&Math.hypot(player.x-beast.x,player.y-beast.y)<23)lose();for(const b of bots){if(b.alive&&Math.hypot(b.x-beast.x,b.y-beast.y)<22){b.alive=false;beast.target=null;toast(`${b.name} HAS BEEN TAKEN`);break;}}
}
function locFor(x,y){return areaAt(x,y);}
function update(dt){if(!running)return;timeLeft=Math.max(0,timeLeft-dt);if(timeLeft<=0){win('survival');return;}whistleCooldown=Math.max(0,whistleCooldown-dt);player.noise=Math.max(0,player.noise-dt);for(const b of bots)b.noise=Math.max(0,b.noise-dt);
  let x=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+touch.x,y=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+touch.y,mag=Math.hypot(x,y);if(mag){x/=mag;y/=mag;player.face=Math.atan2(y,x);let run=(keys.shift||keys.run)&&stamina>0&&!crouching,speed=crouching?58:run?215:128,z=locFor(player.x,player.y);if(z.id==='freezer')speed*=.58;if(z.vent)speed*=.68;moveEntity(player,x*speed*dt,y*speed*dt);player.noise=run?.9:.2;if(run)stamina=Math.max(0,stamina-28*dt);else stamina=Math.min(100,stamina+17*dt);}else{stamina=Math.min(100,stamina+21*dt);player.noise=0;}
  player.hidden=crouching&&hides.some(h=>Math.hypot(player.x-h.x,player.y-h.y)<48);updateBots(dt);updateBeast(dt);trainX+=trainDir*310*dt;if(trainX>W-330){trainX=W-330;trainDir=-1;}if(trainX<80){trainX=80;trainDir=1;}
  if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0) $('toast').classList.remove('show');}shake=Math.max(0,shake-dt*18);

