content.text:
.grain{pointer-events:none;position:absolute;inset:0;opacity:.1;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.24'/%3E%3C/svg%3E");mix-blend-mode:screen;z-index:2}
.topbar{position:absolute;z-index:5;top:0;left:0;right:0;height:72px;display:flex;align-items:center;padding:0 28px;border-bottom:1px solid rgba(202,225,211,.13);background:linear-gradient(180deg,rgba(5,11,10,.88),rgba(5,11,10,.18));}
.hud-left,.hud-right{position:absolute;z-index:4;top:91px;display:grid;gap:10px}
.hud-left{left:25px;width:218px}
.hud-right{right:25px;width:235px}
.hud-card,.location-card,.map-card{background:var(--panel);border:1px solid var(--line);backdrop-filter:blur(8px)}
.objective-card strong{font:700 16px 'Barlow Condensed';letter-spacing:.3px}
.location-card{padding:13px 15px}
.location-card strong{font:800 22px 'Barlow Condensed';letter-spacing:1px;display:block}
.map-card{padding:11px 12px}
.map-card canvas{width:100%;height:auto;display:block;margin:7px 0}
.controls{position:absolute;z-index:5;bottom:0;left:0;right:0;height:94px;padding:12px 25px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(0deg,rgba(4,9,8,.95),rgba(4,9,8,.7));border-top:1px solid rgba(202,225,211,.1)}
.toast{position:absolute;z-index:7;top:78px;left:50%;transform:translate(-50%,-20px);padding:10px 18px;background:rgba(8,16,14,.94);border:1px solid rgba(199,243,106,.44);color:var(--green);font-size:9px;letter-spacing:1.2px;opacity:0;transition:.25s;pointer-events:none}
.toast.show{opacity:1;transform:translate(-50%,0)}
.interact-hint{position:absolute;z-index:4;bottom:112px;left:50%;transform:translateX(-50%);font-size:9px;color:#d1dbc9;letter-spacing:1px;text-shadow:0 2px 6px #000}
@media(max-width:850px){.topbar{height:58px;padding:0 14px}
.hud-left{top:69px;left:10px;width:170px;gap:6px}
.hud-right{top:69px;right:10px;width:177px;gap:6px}
.objective-card strong{font-size:14px}
.location-card{padding:9px 10px}
.location-card strong{font-size:18px}
.map-card{padding:8px}
.controls{height:81px;padding:8px 10px}
.interact-hint{bottom:92px;font-size:8px}
.toast{top:63px}
.hud-left{width:145px}
.hud-right{width:153px}
.map-card{display:none}
.location-card strong{font-size:17px}
.hud-left .objective-card strong{font-size:12px}
.controls{justify-content:flex-end}
.map-card{display:none}
.interact-hint{max-width:min(90vw,520px)}
.hud-left{gap:5px}
