@media(max-width:540px){.mobile-joystick{left:10px;bottom:86px;width:106px;height:106px}.joystick-knob{width:42px;height:42px;margin:-21px}.task-card{max-width:170px}.task-card strong{font-size:8px}.task-card li{font-size:6px}.hud-left{gap:5px}.hud-left .task-card{padding:8px}}
/* Keep the playfield readable beneath the compact HUD. */
.hud-card,.location-card,.map-card{background:rgba(9,18,17,.58);backdrop-filter:blur(3px)}
.topbar{background:linear-gradient(180deg,rgba(5,11,10,.62),rgba(5,11,10,.08));border-bottom-color:rgba(202,225,211,.08)}
.controls{height:76px;background:linear-gradient(0deg,rgba(4,9,8,.76),rgba(4,9,8,.24));border-top-color:rgba(202,225,211,.07)}
.hud-left,.hud-right{gap:7px}
.objective-card,.vitals,.task-card,.location-card,.map-card{box-shadow:0 6px 24px rgba(0,0,0,.12)}
@media(max-width:850px){.controls{height:68px}.hud-card,.location-card{background:rgba(9,18,17,.46)}}

